package com.centralplay.app.ui;
import android.content.Intent;import android.os.Bundle;import android.view.*;import android.widget.TextView;import androidx.annotation.NonNull;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.*;import com.centralplay.app.R;import com.centralplay.app.model.*;import com.google.android.material.appbar.MaterialToolbar;import com.google.gson.Gson;
public class SeriesDetailActivity extends AppCompatActivity{@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_series_detail);Gson g=new Gson();SeriesEntry s=g.fromJson(getIntent().getStringExtra("series"),SeriesEntry.class);if(s==null){finish();return;}MaterialToolbar tb=findViewById(R.id.toolbar);tb.setTitle(s.title);tb.setNavigationOnClickListener(v->finish());((TextView)findViewById(R.id.description)).setText(s.description);RecyclerView rv=findViewById(R.id.episodes);rv.setLayoutManager(new LinearLayoutManager(this));rv.setAdapter(new EpAdapter(s));}private class EpAdapter extends RecyclerView.Adapter<EpAdapter.H>{private final SeriesEntry s;EpAdapter(SeriesEntry s){this.s=s;}@NonNull public H onCreateViewHolder(@NonNull ViewGroup p,int v){return new H(LayoutInflater.from(p.getContext()).inflate(R.layout.item_episode,p,false));}public void onBindViewHolder(@NonNull H h,int p){Episode e=s.episodes.get(p);h.t.setText("T"+e.season+" · E"+e.number+" — "+e.title);h.st.setText(e.description);h.itemView.setOnClickListener(v->{MediaEntry m=new MediaEntry();m.id=e.id;m.type="episode";m.title=s.title+" — "+e.title;m.description=e.description;m.streamUrl=e.streamUrl;m.backupUrls=e.backupUrls;Intent i=new Intent(SeriesDetailActivity.this,PlayerActivity.class);i.putExtra("media",new Gson().toJson(m));startActivity(i);});}public int getItemCount(){return s.episodes==null?0:s.episodes.size();}class H extends RecyclerView.ViewHolder{TextView t,st;H(View v){super(v);t=v.findViewById(R.id.title);st=v.findViewById(R.id.subtitle);}}}}
